void
)
const
{
return
"R-ladder"
; }
  };
//+------------------------------------------------------------------+
//| Lock whole R multiples as they are cleared                       |
//+------------------------------------------------------------------+
double
CTrailRRLadder::ComputeStopLevel(
const
STrailContext &ctx)
  {
//--- Without the original risk there is no R to count in
if
(ctx.originalRisk <=
0
|| m_stepR <=
0
|| ctx.profitDistance <=
0
)
return
0.0
;
double
profitR = ctx.profitDistance / ctx.originalRisk;
//--- The highest rung fully cleared
double
rung =
MathFloor
(profitR / m_stepR);
if
(rung <
1
)
return
0.0
;
//--- Lock this far behind the rung that was reached
double
lockR = (rung * m_stepR) - m_lagR;
if
(lockR <=
0
)
return
0.0
;
double
lockDistance = lockR * ctx.originalRisk;
if
(ctx.positionType ==
POSITION_TYPE_BUY
)
return
ctx.entryPrice + lockDistance;
return
ctx.entryPrice - lockDistance;
  }
Nothing happens until profit reaches a whole rung. Then the stop jumps to lock a whole number of R and stays there until the next rung. The step sets the spacing between rungs, and the lag sets how far behind the reached rung the stop is locked.
