int
cached =
ArraySize
(m_riskIds);
for
(
int
i =
0
; i < cached; i++)
if
(m_riskIds[i] == positionId)
return
m_riskValues[i];
if
(!
HistorySelectByPosition
(positionId))
return
0.0
;
//--- Nothing in history for this position yet: ask again next time, cache nothing
int
orders =
HistoryOrdersTotal
();
if
(orders <=
0
)
return
0.0
;
//--- The opening order is the one whose ticket is the position's identifier.
//--- No other order is taken in its place.
bool
found =
false
;
for
(
int
