        }
//--- A stop that cannot be read is not a missing stop: ask again next time
double
orderSL =
0.0
;
if
(found && !
HistoryOrderGetDouble
(positionId,
ORDER_SL
, orderSL))
return
0.0
;
double
originalRisk = (orderSL >
0
) ?
MathAbs
(entryPrice - orderSL) :
0.0
