bool
sent    = m_trade.PositionModify(ctx.ticket, normalized, ctx.currentTP);
uint
retcode = m_trade.ResultRetcode();
//--- A true return means the request passed CTrade's own checks
if
(!sent || (retcode !=
TRADE_RETCODE_DONE
&& retcode !=
TRADE_RETCODE_PLACED
))
     {
