iTime
(m_symbol,
PERIOD_CURRENT
,
0
);
PrintFormat
(
"Trailing: modifying #%I64u to %.*f was refused. Retcode: %u (%s). Paused until the next bar."
,
                  ctx.ticket, ctx.digits, normalized,
                  retcode, m_trade.ResultRetcodeDescription());
return
false
;
     }
if
(m_cfg.verbose)
     {
double
movedPoints = (ctx.currentSL >
0
)
                           ?
MathAbs
(normalized - ctx.currentSL) / ctx.point
                           :
0.0
;
PrintFormat
(
"Trailing [%s]: #%I64u stop %.*f -> %.*f (+%.1f pts)"
,
MethodName(), ctx.ticket,
